import io
import pandas as pd


def load(text):
    df = pd.read_csv(io.StringIO(text))
    df["timestamp"] = pd.to_datetime(df["timestamp"], utc=True).dt.tz_convert("Europe/London")
    return df.set_index("timestamp").sort_index()


def daily(df):
    return df["visits"].resample("D").sum()


def trend(days):
    out = pd.DataFrame({"visits": days})
    out["avg7"] = days.rolling(7, min_periods=1).mean().round(1)
    out["wow"] = (days.pct_change(7) * 100).round(1)
    return out
